insert into public.exercises
  (slug, name, equipment, primary_muscle, media_start_path, media_end_path, cue, steps)
values
  ('hip-thrust-barra', 'Hip thrust com barra', 'barra', 'Glúteo máximo', '/exercicios/hip-thrust-barra-0.jpg', '/exercicios/hip-thrust-barra-1.jpg', 'O erro comum é subir com a lombar em vez do quadril. Quem empurra é o glúteo.', array['Apoie a escápula na borda do banco, barra na dobra do quadril, pés na largura dos ombros.', 'Empurre pelo calcanhar até o tronco ficar paralelo ao chão, com o queixo baixo.', 'Aperte o glúteo um segundo no topo e desça sem encostar no chão.']),
  ('elevacao-pelvica-maquina', 'Elevação pélvica na máquina', 'máquina', 'Glúteo máximo', null, null, 'Mesma cadência da barra. A carga não se compara com a do hip thrust livre.', array['Ajuste o encosto para o apoio ficar na dobra do quadril, não na barriga.', 'Empurre até estender o quadril, sem jogar a lombar para trás.', 'Um segundo de aperto no topo e dois segundos na volta.']),
  ('rdl-halteres', 'Levantamento terra romeno', 'halteres', 'Posterior de coxa', null, null, 'Não é agachar: o joelho quase não dobra, quem desce é o quadril.', array['Em pé, halteres à frente das coxas, joelhos levemente destravados.', 'Leve o quadril para trás deslizando os halteres pela perna, coluna neutra.', 'Pare quando sentir o posterior alongar e volte empurrando o quadril à frente.']),
  ('pull-through', 'Pull-through na polia', 'polia', 'Glúteo máximo', '/exercicios/pull-through-0.jpg', '/exercicios/pull-through-1.jpg', 'Ensina o padrão do terra romeno sem carga na coluna.', array['De costas para a polia baixa, corda entre as pernas, dois passos à frente.', 'Leve o quadril para trás deixando a corda descer, tronco quase paralelo ao chão.', 'Estenda o quadril à frente apertando o glúteo, sem puxar com o braço.']),
  ('extensao-45-gluteo', 'Extensão 45° foco glúteo', 'máquina', 'Glúteo máximo', '/exercicios/extensao-45-gluteo-0.jpg', '/exercicios/extensao-45-gluteo-1.jpg', 'Passar do alinhamento do quadril tira o glúteo e joga o esforço na lombar.', array['Apoio na coxa, abaixo do osso do quadril, pés abertos e virados para fora.', 'Desça até sentir o posterior, com a coluna arredondada de propósito e o queixo baixo.', 'Suba só até o tronco alinhar com a perna, sem passar disso.']),
  ('cadeira-flexora-sentada', 'Cadeira flexora sentada', 'máquina', 'Posterior de coxa', '/exercicios/cadeira-flexora-sentada-0.jpg', '/exercicios/cadeira-flexora-sentada-1.jpg', 'Sentada alonga mais que deitada. Dois segundos na volta.', array['Encoste bem o quadril e trave o apoio da coxa antes de começar.', 'Dobre o joelho até o fim do curso, sem tirar a coxa do apoio.', 'Volte em dois segundos, controlando até o joelho quase estender.']),
  ('coice-polia', 'Coice na polia', 'polia', 'Glúteo máximo', '/exercicios/coice-polia-0.jpg', '/exercicios/coice-polia-1.jpg', 'Se a lombar arqueia para a perna subir mais, a amplitude útil já acabou.', array['Tornozeleira no pé, tronco inclinado à frente segurando o apoio.', 'Leve a perna para trás com o joelho quase estendido, parando na linha do tronco.', 'Um segundo de aperto e volta controlada, sem arquear a lombar.']),
  ('coice-maquina', 'Coice na máquina', 'máquina', 'Glúteo máximo', null, null, 'Se a lombar arqueia para a perna subir mais, a amplitude útil já acabou.', array['Apoie o tronco no encosto e alinhe o joelho com o eixo da máquina.', 'Empurre a plataforma para trás até estender o quadril.', 'Um segundo de aperto e volta em dois segundos.']),
  ('abducao-polia', 'Abdução em pé na polia', 'polia', 'Glúteo médio', null, null, 'Três segundos na volta. Só sobe carga quando fechar 20 repetições.', array['Tornozeleira na perna de fora, de lado para a polia, mão no apoio.', 'Abra a perna para o lado sem girar o quadril nem inclinar o tronco.', 'Volte em três segundos, resistindo à polia até o pé quase tocar o chão.']),
  ('cadeira-abdutora', 'Cadeira abdutora', 'máquina', 'Glúteo médio', '/exercicios/cadeira-abdutora-0.jpg', '/exercicios/cadeira-abdutora-1.jpg', 'Tronco inclinado uns 30° à frente: é o que leva o estímulo para o glúteo médio.', array['Sente e incline o tronco uns 30° à frente, apoiando as mãos nos joelhos.', 'Abra até o fim do curso sem jogar o tronco para trás.', 'Volte em dois segundos, sem deixar as placas baterem.']),
  ('goblet-squat', 'Goblet squat', 'halteres', 'Quadríceps', '/exercicios/goblet-squat-0.jpg', '/exercicios/goblet-squat-1.jpg', 'Profundidade completa, joelhos na linha dos pés.', array['Halter na vertical junto ao peito, cotovelos por dentro dos joelhos.', 'Desça entre os calcanhares até a coxa passar da paralela.', 'Suba empurrando o chão, mantendo o peito alto.']),
  ('agachamento-livre', 'Agachamento livre', 'barra', 'Quadríceps', '/exercicios/agachamento-livre-0.jpg', '/exercicios/agachamento-livre-1.jpg', 'Profundidade completa. Nunca até a falha.', array['Barra apoiada no trapézio, pés na largura dos ombros e levemente abertos.', 'Desça com o quadril e o joelho juntos, joelho seguindo a linha do pé.', 'Suba sem deixar o quadril subir antes do peito.']),
  ('hack-squat', 'Agachamento hack', 'máquina', 'Quadríceps', '/exercicios/hack-squat-0.jpg', '/exercicios/hack-squat-1.jpg', 'Descolar a lombar do encosto no fundo é o que machuca neste aparelho.', array['Pés na metade da plataforma, na largura dos ombros.', 'Desça até a coxa passar da paralela, lombar colada no encosto.', 'Suba sem travar o joelho no topo.']),
  ('leg-press-45', 'Leg press 45°', 'máquina', 'Quadríceps', '/exercicios/leg-press-45-0.jpg', '/exercicios/leg-press-45-1.jpg', 'Pés na altura média, sem tirar a lombar do encosto.', array['Pés na altura média da plataforma, na largura dos ombros.', 'Desça até o joelho chegar perto do peito, sem descolar o quadril do banco.', 'Empurre pelo meio do pé, sem travar o joelho.']),
  ('cadeira-extensora', 'Cadeira extensora', 'máquina', 'Quadríceps', '/exercicios/cadeira-extensora-0.jpg', '/exercicios/cadeira-extensora-1.jpg', 'A carga certa é a que deixa segurar um segundo no topo sem tremer.', array['Ajuste o encosto para o joelho ficar na linha do eixo da máquina.', 'Estenda até o fim e segure um segundo no topo.', 'Desça em dois segundos, sem deixar as placas baterem.']),
  ('bulgaro', 'Agachamento búlgaro', 'halteres', 'Quadríceps', null, null, 'Tronco 15 a 20° à frente para levar mais carga ao glúteo.', array['Peito do pé de trás no banco, pé da frente a um passo largo à frente.', 'Desça na vertical até o joelho de trás quase tocar o chão.', 'Suba empurrando pelo calcanhar da frente, tronco levemente inclinado.']),
  ('step-up', 'Step-up alto', 'halteres', 'Glúteo máximo', '/exercicios/step-up-0.jpg', '/exercicios/step-up-1.jpg', 'Se o pé de baixo dá impulso, a perna de cima parou de trabalhar.', array['Banco na altura em que a coxa fica paralela ao chão ao subir o pé.', 'Suba empurrando só pelo calcanhar da perna de cima.', 'Desça devagar, encostando a ponta do pé de trás sem apoiar o peso.']),
  ('panturrilha-em-pe', 'Panturrilha em pé', 'máquina', 'Panturrilha', '/exercicios/panturrilha-em-pe-0.jpg', '/exercicios/panturrilha-em-pe-1.jpg', 'Sem pique. A repetição que conta é a que passa pela posição alongada.', array['Ponta do pé na plataforma, calcanhar livre, joelho estendido.', 'Desça o calcanhar até alongar e segure um segundo embaixo.', 'Suba até a ponta do pé, sem dobrar o joelho.']),
  ('panturrilha-sentada', 'Panturrilha sentada', 'máquina', 'Panturrilha', '/exercicios/panturrilha-sentada-0.jpg', '/exercicios/panturrilha-sentada-1.jpg', 'Sem pique. A repetição que conta é a que passa pela posição alongada.', array['Apoio sobre a coxa, perto do joelho, ponta do pé na plataforma.', 'Desça o calcanhar até o fim e segure um segundo.', 'Suba com força até a ponta do pé.']),
  ('remada-curvada-halteres', 'Remada curvada com halteres', 'halteres', 'Costas', '/exercicios/remada-curvada-halteres-0.jpg', '/exercicios/remada-curvada-halteres-1.jpg', 'Puxe para o quadril com as escápulas retraídas. Um segundo no final.', array['Quadril para trás até o tronco ficar quase paralelo, coluna neutra.', 'Puxe os halteres para o quadril, cotovelo junto ao corpo.', 'Um segundo apertando a escápula e desça controlando.']),
  ('remada-baixa-sentada', 'Remada baixa sentada', 'polia', 'Costas', '/exercicios/remada-baixa-sentada-0.jpg', '/exercicios/remada-baixa-sentada-1.jpg', 'Pegada neutra, escápulas retraídas.', array['Sentada, peito alto, joelho levemente dobrado.', 'Puxe o triângulo para o abdômen sem jogar o tronco para trás.', 'Volte deixando a escápula abrir no fim, sem soltar o peso.']),
  ('serrote', 'Serrote com halter', 'halteres', 'Costas', '/exercicios/serrote-0.jpg', '/exercicios/serrote-1.jpg', 'Cotovelo aberto tira as costas e entrega o movimento para o ombro.', array['Mão e joelho no banco, coluna paralela ao chão.', 'Puxe o halter para o quadril com o cotovelo colado no corpo.', 'Desça até o braço estender, sem girar o tronco.']),
  ('remada-unilateral-maquina', 'Remada unilateral na máquina', 'máquina', 'Costas', '/exercicios/remada-unilateral-maquina-0.jpg', '/exercicios/remada-unilateral-maquina-1.jpg', 'Cotovelo aberto tira as costas e entrega o movimento para o ombro.', array['Peito no apoio, ajuste o banco para a pegada ficar na altura do abdômen.', 'Puxe um braço por vez, cotovelo junto ao corpo.', 'Volte deixando a escápula abrir, sem girar o tronco.']),
  ('supino-halteres', 'Supino com halteres', 'halteres', 'Peito', '/exercicios/supino-halteres-0.jpg', '/exercicios/supino-halteres-1.jpg', 'Escápula solta no banco é o que vira dor no ombro depois.', array['Escápulas retraídas no banco, pés firmes no chão.', 'Desça os halteres até a altura do peito, cotovelos a uns 45°.', 'Empurre até quase estender, sem bater os halteres.']),
  ('supino-maquina', 'Supino na máquina', 'máquina', 'Peito', '/exercicios/supino-maquina-0.jpg', '/exercicios/supino-maquina-1.jpg', 'Escápulas retraídas.', array['Ajuste o banco para a pegada ficar na altura do meio do peito.', 'Empurre até quase estender, sem tirar a escápula do encosto.', 'Volte em dois segundos até sentir o peito alongar.']),
  ('supino-inclinado-halteres', 'Supino inclinado com halteres', 'halteres', 'Peito', '/exercicios/supino-inclinado-halteres-0.jpg', '/exercicios/supino-inclinado-halteres-1.jpg', 'Acima de 30° o exercício vira desenvolvimento de ombro.', array['Banco a 30°, escápulas retraídas, pés firmes.', 'Desça até a altura da clavícula, cotovelos a uns 45°.', 'Empurre sem travar o cotovelo no topo.']),
  ('supino-inclinado-maquina', 'Supino inclinado na máquina', 'máquina', 'Peito', '/exercicios/supino-inclinado-maquina-0.jpg', '/exercicios/supino-inclinado-maquina-1.jpg', 'Ajuste o banco antes: pegada alta demais joga tudo no ombro.', array['Ajuste o banco para a pegada ficar na altura da parte alta do peito.', 'Empurre até quase estender, escápula colada no encosto.', 'Volte em dois segundos.']),
  ('face-pull', 'Face pull na polia', 'polia', 'Deltoide posterior', '/exercicios/face-pull-0.jpg', '/exercicios/face-pull-1.jpg', 'Corda na altura do rosto, cotovelos altos, rotação externa no final.', array['Corda na polia alta, na altura do rosto, um passo para trás.', 'Puxe separando as pontas da corda, com o cotovelo acima da linha do punho.', 'Termine com as mãos ao lado da cabeça e volte controlando.']),
  ('desenvolvimento-halteres', 'Desenvolvimento com halteres', 'halteres', 'Ombro', '/exercicios/desenvolvimento-halteres-0.jpg', '/exercicios/desenvolvimento-halteres-1.jpg', 'Glúteo contraído, costela fechada.', array['Sentada com encosto, halteres na altura da orelha, cotovelo à frente.', 'Empurre para cima sem jogar a costela para a frente.', 'Desça até a altura da orelha, controlando.']),
  ('desenvolvimento-maquina', 'Desenvolvimento na máquina', 'máquina', 'Ombro', '/exercicios/desenvolvimento-maquina-0.jpg', '/exercicios/desenvolvimento-maquina-1.jpg', 'Costela fechada.', array['Ajuste o banco para a pegada ficar na altura do ombro.', 'Empurre para cima sem travar o cotovelo.', 'Desça até o cotovelo passar um pouco da linha do ombro.']),
  ('crucifixo-inverso', 'Crucifixo inverso', 'halteres', 'Deltoide posterior', '/exercicios/crucifixo-inverso-0.jpg', '/exercicios/crucifixo-inverso-1.jpg', 'Dois segundos na volta. É postura, não volume.', array['Sentada na ponta do banco, tronco sobre a coxa, halteres embaixo.', 'Abra os braços para o lado com o cotovelo levemente dobrado.', 'Pare na linha do ombro e volte em dois segundos.']),
  ('crucifixo-inverso-maquina', 'Crucifixo inverso na máquina', 'máquina', 'Deltoide posterior', null, null, 'É postura, não volume. Carga leve o bastante para não puxar com o trapézio.', array['Peito no apoio, pegada na altura do ombro.', 'Abra para trás até a linha do ombro, sem encolher o pescoço.', 'Volte em dois segundos, sem deixar as placas baterem.']),
  ('elevacao-lateral', 'Elevação lateral', 'halteres', 'Deltoide lateral', '/exercicios/elevacao-lateral-0.jpg', '/exercicios/elevacao-lateral-1.jpg', 'Dose de manutenção, de propósito. Não precisa crescer aqui.', array['Em pé, halteres ao lado do corpo, cotovelo levemente dobrado.', 'Suba pelo lado até a altura do ombro, sem encolher o trapézio.', 'Desça em dois segundos.']),
  ('triceps-polia', 'Tríceps na polia', 'polia', 'Tríceps', '/exercicios/triceps-polia-0.jpg', '/exercicios/triceps-polia-1.jpg', 'Cotovelo que sai do lugar transforma o exercício em remada.', array['Barra na polia alta, cotovelo colado ao lado do corpo.', 'Estenda até o fim sem mover o cotovelo do lugar.', 'Volte até o antebraço passar da paralela.']),
  ('triceps-testa', 'Tríceps testa', 'halteres', 'Tríceps', '/exercicios/triceps-testa-0.jpg', '/exercicios/triceps-testa-1.jpg', 'Cotovelo abrindo para os lados tira o tríceps do movimento.', array['Deitada no banco, braços na vertical, cotovelo apontado para o teto.', 'Dobre só o cotovelo, levando o peso até perto da testa.', 'Estenda sem deixar o cotovelo abrir para os lados.']),
  ('rosca-halteres', 'Rosca com halteres', 'halteres', 'Bíceps', '/exercicios/rosca-halteres-0.jpg', '/exercicios/rosca-halteres-1.jpg', 'Sem balanço de tronco.', array['Em pé, halteres ao lado do corpo, palma para a frente.', 'Suba dobrando só o cotovelo, sem mover o ombro.', 'Desça até estender o braço, em dois segundos.']),
  ('rosca-alternada', 'Rosca alternada', 'halteres', 'Bíceps', '/exercicios/rosca-alternada-0.jpg', '/exercicios/rosca-alternada-1.jpg', 'Sem balanço de tronco.', array['Em pé, um halter de cada lado, palma para a frente.', 'Suba um braço por vez, mantendo o outro estendido.', 'Desça controlando antes de começar o outro lado.']),
  ('rosca-maquina', 'Rosca na máquina', 'máquina', 'Bíceps', '/exercicios/rosca-maquina-0.jpg', '/exercicios/rosca-maquina-1.jpg', 'Descolar o braço do apoio é o jeito de tirar o bíceps e usar o ombro.', array['Ajuste o banco para a axila encostar no alto do apoio.', 'Suba dobrando o cotovelo, sem descolar o braço do apoio.', 'Desça até quase estender, em dois segundos.']),
  ('abdominal-solo', 'Abdominal no solo', 'peso do corpo', 'Core', '/exercicios/abdominal-solo-0.jpg', '/exercicios/abdominal-solo-1.jpg', 'Sem puxar o pescoço com as mãos.', array['Deitada, joelho dobrado, mãos cruzadas no peito.', 'Enrole a coluna tirando só a escápula do chão.', 'Desça devagar até a escápula encostar.']),
  ('abdominal-maquina', 'Abdominal na máquina', 'máquina', 'Core', '/exercicios/abdominal-maquina-0.jpg', '/exercicios/abdominal-maquina-1.jpg', 'Movimento vem da coluna, não do quadril.', array['Ajuste o apoio para ficar na altura do peito.', 'Enrole a coluna à frente, sem puxar com o braço.', 'Volte em dois segundos, sem deixar as placas baterem.']),
  ('prancha', 'Prancha', 'peso do corpo', 'Core', '/exercicios/prancha-0.jpg', '/exercicios/prancha-1.jpg', 'Glúteo contraído, quadril na linha dos ombros.', array['Cotovelo embaixo do ombro, antebraço no chão.', 'Contraia glúteo e abdômen até o corpo virar uma linha reta.', 'Respire normal e segure o tempo prescrito.']),
  ('dead-bug', 'Dead bug', 'peso do corpo', 'Core', '/exercicios/dead-bug-0.jpg', '/exercicios/dead-bug-1.jpg', 'Lombar colada no chão o tempo inteiro.', array['Deitada, braço apontado para o teto, joelho e quadril a 90°.', 'Estenda o braço e a perna opostos até quase o chão.', 'Volte e troque, sem deixar a lombar descolar.'])
